        for (var j = 0; j < L.length; j++) h += '<li>' + esc(L[j]) + '</li>';
        h += '</ul>';
      }
      h += '</div>';
    }
    if (files.length) {
      h += '<div class="lvmUwS">' + esc(tr('uw_files')) + '</div>';
